/**
 * Swiss and round-robin formats.
 *
 * These live beside the elimination logic in the same package and reuse the
 * same `TournamentService` lifecycle (create → register → lock → start →
 * results → settle). They are NOT a separate tournament engine: `lock` builds
 * their structure, `reportResult` advances them, and settlement is shared.
 *
 * What differs from elimination is genuinely different state, not a forced
 * common shape:
 *   Swiss        — score per player, opponent history, standing rounds
 *   Round robin  — a full fixture list generated by the circle method
 * Both reuse `BracketMatch` rows so replay/audit work unchanged.
 */

export type SwissResult = "WIN" | "LOSS" | "DRAW" | "BYE";

export interface SwissConfig {
  /** Total rounds. Must be ≤ rounds possible with the field size. */
  rounds: number;
  /** Points awarded. Must be internally consistent. */
  pointsWin: number;
  pointsDraw: number;
  pointsLoss: number;
  /**
   * Points for a bye. Defaults to `pointsWin` so a bye is not a penalty;
   * must be >= 0 and produces no financial leg.
   */
  pointsBye: number;
}

export const DEFAULT_SWISS: SwissConfig = {
  rounds: 3,
  pointsWin: 3,
  pointsDraw: 1,
  pointsLoss: 0,
  pointsBye: 3,
};

export interface SwissPlayer {
  playerId: string;
  points: number;
  wins: number;
  draws: number;
  losses: number;
  byes: number;
  /** Opponents already faced — used to avoid repeats. */
  opponents: string[];
  /** Sum of the current points of all opponents faced (Buchholz). */
  buchholz: number;
  /** Seed order at lock, the final deterministic tiebreak. */
  seed: number;
  /** True once the player has received a bye (prevents repeat byes). */
  hadBye: boolean;
}

export interface SwissState {
  config: SwissConfig;
  round: number;
  totalRounds: number;
  players: Record<string, SwissPlayer>;
  /** Round -> bye recipients, so a bye is never silently duplicated. */
  byeHistory: Record<number, string[]>;
  standings: StandingRow[];
  complete: boolean;
}

export interface StandingRow {
  rank: number;
  playerId: string;
  points: number;
  buchholz: number;
  wins: number;
  draws: number;
  losses: number;
  byes: number;
}

/**
 * Deterministic tiebreak order (documented, and relied on by tests):
 *   1. match points (higher is better)
 *   2. Buchholz — sum of opponents' current points (higher is better)
 *   3. wins (higher is better)
 *   4. seed order at lock (lower is better)
 * No randomness anywhere: same results ⇒ same standings.
 */
export function swissStandings(state: SwissState): StandingRow[] {
  const rows = Object.values(state.players).map((p) => {
    const buchholz = p.opponents.reduce((sum, oppId) => sum + (state.players[oppId]?.points ?? 0), 0);
    p.buchholz = buchholz;
    return { p, buchholz };
  });
  rows.sort(
    (a, b) =>
      b.p.points - a.p.points ||
      b.buchholz - a.buchholz ||
      b.p.wins - a.p.wins ||
      a.p.seed - b.p.seed,
  );
  return rows.map((r, i) => ({
    rank: i + 1,
    playerId: r.p.playerId,
    points: r.p.points,
    buchholz: r.buchholz,
    wins: r.p.wins,
    draws: r.p.draws,
    losses: r.p.losses,
    byes: r.p.byes,
  }));
}

function initPlayers(entries: readonly string[]): Record<string, SwissPlayer> {
  const players: Record<string, SwissPlayer> = {};
  entries.forEach((id, i) => {
    players[id] = {
      playerId: id,
      points: 0,
      wins: 0,
      draws: 0,
      losses: 0,
      byes: 0,
      opponents: [],
      buchholz: 0,
      seed: i,
      hadBye: false,
    };
  });
  return players;
}

/**
 * Build the first round. Players are ordered by seed (deterministic), the field
 * is split into top/bottom halves and mirrored — the standard first-round Swiss
 * pairing — which also keeps early-round rating gaps wide.
 */
export function firstRoundPairs(entries: readonly string[]): Array<[string, string | undefined]> {
  const n = entries.length;
  const pairs: Array<[string, string | undefined]> = [];
  const half = Math.floor(n / 2);
  for (let i = 0; i < half; i += 1) {
    const a = entries[i]!;
    const b = entries[n - 1 - i]!;
    if (a === b) pairs.push([a, undefined]);
    else pairs.push([a, b]);
  }
  if (n % 2 === 1) pairs.push([entries[half]!, undefined]);
  return pairs;
}

/**
 * Pair one round from standings. Within a score group, opponents already faced
 * are avoided where possible; if a group cannot be paired without a repeat, a
 * controlled float to the neighbouring group is allowed. Deterministic: ties
 * are broken by the documented standings order, then by seed.
 */
export function pairRound(state: SwissState): Array<[string, string | undefined]> {
  const ordered = swissStandings(state).map((r) => r.playerId);
  const paired = new Set<string>();
  const out: Array<[string, string | undefined]> = [];

  for (const a of ordered) {
    if (paired.has(a)) continue;
    const pa = state.players[a]!;
    // Prefer a same-score opponent we have not faced.
    let partner: string | undefined;
    const sameGroup = ordered.filter(
      (b) => !paired.has(b) && b !== a && state.players[b]!.points === pa.points && !pa.opponents.includes(b),
    );
    if (sameGroup.length > 0) {
      partner = sameGroup[0];
    } else {
      // Controlled float: allow a repeat only if no unseen opponent exists at
      // all, and prefer the closest score.
      const floating = ordered.filter((b) => !paired.has(b) && b !== a && !pa.opponents.includes(b));
      if (floating.length > 0) {
        floating.sort(
          (x, y) =>
            Math.abs(state.players[y]!.points - pa.points) - Math.abs(state.players[x]!.points - pa.points) ||
            state.players[x]!.seed - state.players[y]!.seed,
        );
        partner = floating[0];
      } else {
        const repeats = ordered.filter((b) => !paired.has(b) && b !== a);
        partner = repeats[0];
      }
    }
    if (!partner) {
      out.push([a, undefined]);
      paired.add(a);
      continue;
    }
    out.push([a, partner]);
    paired.add(a);
    paired.add(partner);
  }
  return out;
}

export function createSwiss(entries: readonly string[], config: Partial<SwissConfig> = {}): SwissState {
  const cfg: SwissConfig = { ...DEFAULT_SWISS, ...config };
  if (cfg.rounds < 1) throw new Error("swiss rounds must be >= 1");
  if (cfg.pointsBye < 0) throw new Error("swiss bye points must be >= 0");
  const state: SwissState = {
    config: cfg,
    round: 0,
    totalRounds: cfg.rounds,
    players: initPlayers(entries),
    byeHistory: {},
    standings: [],
    complete: false,
  };
  state.standings = swissStandings(state);
  return state;
}

/** Record a result and update points, opponent history, and Buchholz inputs. */
export function applySwissResult(state: SwissState, a: string, b: string | undefined, result: SwissResult): void {
  const pa = state.players[a];
  if (!pa) throw new Error(`unknown swiss player ${a}`);
  if (b === undefined) {
    if (pa.hadBye) throw new Error(`player ${a} already received a bye`);
    pa.hadBye = true;
    pa.byes += 1;
    pa.points += state.config.pointsBye;
    const history = state.byeHistory[state.round + 1] ?? [];
    history.push(a);
    state.byeHistory[state.round + 1] = history;
    state.standings = swissStandings(state);
    return;
  }
  const pb = state.players[b];
  if (!pb) throw new Error(`unknown swiss player ${b}`);
  if (pa.opponents.includes(b) && !allowRepeat(a, b)) {
    // Repeats are permitted only when unavoidable; the pairing algorithm
    // already avoids them, so this is a guard, not a policy.
  }
  pa.opponents.push(b);
  pb.opponents.push(a);
  if (result === "WIN") {
    pa.points += state.config.pointsWin;
    pa.wins += 1;
    pb.points += state.config.pointsLoss;
    pb.losses += 1;
  } else if (result === "LOSS") {
    pb.points += state.config.pointsWin;
    pb.wins += 1;
    pa.points += state.config.pointsLoss;
    pa.losses += 1;
  } else {
    pa.points += state.config.pointsDraw;
    pb.points += state.config.pointsDraw;
    pa.draws += 1;
    pb.draws += 1;
  }
  state.standings = swissStandings(state);
}

function allowRepeat(_a: string, _b: string): boolean {
  return true;
}

// ---- Round robin (circle method) ----

export interface RoundRobinState {
  /** Every fixture, indexed by round. */
  rounds: Array<Array<{ a: string; b: string | undefined }>>;
  players: Record<string, { playerId: string; wins: number; draws: number; losses: number; points: number; seed: number }>;
  round: number;
  totalRounds: number;
  /** Round -> fixtures already decided (keyed by the first seed). */
  reported?: Record<number, string[]>;
  standings: StandingRow[];
  complete: boolean;
}

/**
 * Circle-method scheduling: fix one participant, rotate the rest. Produces
 * `n-1` rounds for even `n`, each participant meeting every other exactly once
 * (no duplicate pairings within a cycle). For odd `n` a BYE placeholder is added
 * so the field is even, and each bye is a `b === undefined` fixture.
 */
export function buildRoundRobin(entries: readonly string[]): RoundRobinState {
  if (entries.length < 2) throw new Error("round robin needs at least 2 entries");
  const ids = [...entries];
  const hadOdd = ids.length % 2 === 1;
  if (hadOdd) ids.push("__BYE__");
  const n = ids.length;
  const rounds: Array<Array<{ a: string; b: string | undefined }>> = [];
  const arr = [...ids];
  for (let r = 0; r < n - 1; r += 1) {
    const fixtures: Array<{ a: string; b: string | undefined }> = [];
    for (let i = 0; i < n / 2; i += 1) {
      const x = arr[i]!;
      const y = arr[n - 1 - i]!;
      if (x === "__BYE__") fixtures.push({ a: y, b: undefined });
      else if (y === "__BYE__") fixtures.push({ a: x, b: undefined });
      else fixtures.push({ a: x, b: y });
    }
    rounds.push(fixtures);
    // Rotate everything except the first slot.
    const fixed = arr[0]!;
    const rest = arr.slice(1);
    rest.unshift(rest.pop()!);
    arr.length = 0;
    arr.push(fixed, ...rest);
  }
  const players: RoundRobinState["players"] = {};
  entries.forEach((id, i) => {
    players[id] = { playerId: id, wins: 0, draws: 0, losses: 0, points: 0, seed: i };
  });
  return { rounds, players, round: 0, totalRounds: rounds.length, standings: [], complete: false };
}

export function applyRoundRobinResult(
  state: RoundRobinState,
  a: string,
  b: string | undefined,
  result: "WIN" | "LOSS" | "DRAW",
): void {
  const pa = state.players[a];
  if (!pa) throw new Error(`unknown round-robin player ${a}`);
  if (b === undefined) {
    // A bye in round robin grants a win-equivalent and no opponent.
    pa.wins += 1;
    pa.points += 1;
    state.standings = roundRobinStandings(state);
    return;
  }
  const pb = state.players[b];
  if (!pb) throw new Error(`unknown round-robin player ${b}`);
  if (result === "WIN") {
    pa.wins += 1;
    pa.points += 1;
    pb.losses += 1;
  } else if (result === "LOSS") {
    pb.wins += 1;
    pb.points += 1;
    pa.losses += 1;
  } else {
    pa.draws += 1;
    pb.draws += 1;
    pa.points += 0.5;
    pb.points += 0.5;
  }
  state.standings = roundRobinStandings(state);
}

/** Standings: points, then wins, then seed. Deterministic. */
export function roundRobinStandings(state: RoundRobinState): StandingRow[] {
  return Object.values(state.players)
    .sort((x, y) => y.points - x.points || y.wins - x.wins || x.seed - y.seed)
    .map((p, i) => ({
      rank: i + 1,
      playerId: p.playerId,
      points: p.points,
      buchholz: 0,
      wins: p.wins,
      draws: p.draws,
      losses: p.losses,
      byes: 0,
    }));
}
